INSERT INTO fragmento_pdf (fragmento_id,pagina_id,orden_lectura,tipo_fragmento,texto_literal,estado_clasificacion) VALUES (200301015,200301,15,'renglon_literal','a. Tener la calidad de estudiante de pregrado o postgrado de la Universidad Nacional de Colombia.','pendiente');
INSERT INTO fragmento_pdf (fragmento_id,pagina_id,orden_lectura,tipo_fragmento,texto_literal,estado_clasificacion) VALUES (200301016,200301,16,'renglon_literal','b. Si las actividades a desarrollar están relacionadas con docencia, el estudiante deberá tener un Promedio Aritmético Ponder ado Acumulado - P.A.P.A. igual o superior a 3.5. para ','pendiente');
