INSERT INTO fragmento_pdf (fragmento_id,pagina_id,orden_lectura,tipo_fragmento,texto_literal,estado_clasificacion) VALUES (200301018,200301,18,'renglon_literal','c. Si las actividades a desarrollar están relacionadas con investigación, extensión, bienestar universitario o de gestión adm inistrativa el estudiante deberá tener un Promedio ','pendiente');
INSERT INTO fragmento_pdf (fragmento_id,pagina_id,orden_lectura,tipo_fragmento,texto_literal,estado_clasificacion) VALUES (200301019,200301,19,'renglon_literal','Aritmético Ponderado Acumulado - P.A.P.A. igual o superior a 3.0. para estudiantes de pregrado, e igual o superior a 4.0 para estudiantes de posgrado','pendiente');
INSERT INTO fragmento_pdf (fragmento_id,pagina_id,orden_lectura,tipo_fragmento,texto_literal,estado_clasificacion) VALUES (200301020,200301,20,'renglon_literal','d. No ostentar la calidad de monitor académico o becario, salvo para aquellos estudiantes que obtuvieron la beca de posgrado por la distinción de Grado de Honor de la ','pendiente');
