INSERT INTO fragmento_pdf (fragmento_id,pagina_id,orden_lectura,tipo_fragmento,texto_literal,estado_clasificacion) VALUES (200301022,200301,22,'renglon_literal','e. No tener calidad de funcionario público (administrativo o docente de planta) de la Universidad Nacional de Colombia.','pendiente');
INSERT INTO fragmento_pdf (fragmento_id,pagina_id,orden_lectura,tipo_fragmento,texto_literal,estado_clasificacion) VALUES (200301023,200301,23,'renglon_literal','f. Durante el periodo lectivo el Estudiante Auxiliar debe mantener la calidad de estudiante e inscrita al menos la carga mínima exigida por el Estatuto Estudiantil.','pendiente');
