INSERT INTO fragmento_pdf (fragmento_id,pagina_id,orden_lectura,tipo_fragmento,texto_literal,estado_clasificacion) VALUES (200301025,200301,25,'renglon_literal','PARÁGRAFO 1. La figura de Estudiante Auxiliar podrá ser compatible con las modalidades de apoyo a estudiantes en las cuales n o se reciba una retribución económica por la ','pendiente');
