INSERT INTO fragmento_pdf (fragmento_id,pagina_id,orden_lectura,tipo_fragmento,texto_literal,estado_clasificacion) VALUES (200301030,200301,30,'renglon_literal','2. Haber sido admitido por admisión automática, según el literal c del artículo 57 del Acuerdo 008 de 2008 del Consejo Superi or Universitario - Estatuto Estudiantil en sus ','pendiente');
